(()=>{const h=window.ESCAPE_DEMO_DATA.state.dashboard.portfolio_value_history,now=Date.now();for(const [key,step] of Object.entries({day:3600000,week:86400000,month:432000000,year:5184000000})){h.periods[key]=Array.from({length:6},(_,i)=>({at:new Date(now-(5-i)*step).toISOString(),amount:'1000',currency:'DKK',reported_result:String(15+i*8)}))}h.day_start=null;h.day_end=null})();
/* Isolated preview: all requests are answered in memory. There is no network path to a broker. */
(()=>{
 const demo=window.ESCAPE_DEMO_DATA, position=id=>demo.state.dashboard.positions.find(p=>String(p.asset_id)===String(id));
 const now=()=>new Date().toISOString();let serial=0;
 const session=(ticker,asset,signal='WAIT',status='AFVENT')=>({watch_id:'demo-'+ticker,status:'ACTIVE',signal,display_status:status,is_test:false,watch_kind:'candidate',request:{ticker,asset_id:asset,provider:'eodhd',exchange:'TEST',quote_currency:'DKK',activation_reason:'Simuleret overvågning – kun testdata',strategy_id:'TEST',strategy_version:'1',portfolio_ids:[]},strategy_checksum:'TEST',effective_min_interval_s:60,last_computed_signal:'WAIT',data_status:{price:'50',price_status:'FRESH',market_status:'OPEN'},last_calculation_at:now(),last_data_at:now(),data_stale:false,latest_currency:'DKK',latest_calculation:{signal,reason_codes:['SIMULERET_TESTDATA']},last_action_signal:null});
 const sessions=[session('NOVOB','synthetic-asset-NOVOB'),session('TSLA','synthetic-asset-TSLA')];
 const ok=data=>new Response(JSON.stringify(data),{status:200,headers:{'Content-Type':'application/json'}}),bad=()=>new Response(JSON.stringify({error:'Kun testvisning: denne funktion er ikke tilsluttet.'}),{status:403,headers:{'Content-Type':'application/json'}});
 window.fetch=async(input,opts={})=>{
  let u;try{u=new URL(typeof input==='string'?input:input.url,location.href)}catch{return bad()}
  if(u.origin!==location.origin||!u.pathname.startsWith('/api/'))return bad();
  const route=u.pathname.slice(5);let payload={};try{payload=JSON.parse(opts.body||'{}')}catch{return bad()}
  if(route==='session')return ok({authenticated:true,csrf:'test-only',user:demo.state.user});
  if(route==='state'){demo.state.time=now();return ok(demo.state)}
  if(route==='automation')return ok(demo.automation);
  if(route==='reports/desk')return ok(demo.desk);
  if(route==='sector-intelligence'){
   const sectors=['Teknologi','Sundhed','Finans','Industri'];
   const dashboard=JSON.parse(JSON.stringify(demo.state.dashboard));
   dashboard.positions.forEach((p,i)=>p.sector_intelligence={sector:sectors[i%sectors.length],source:'Fiktive demodata'});
   const markets=sectors.map((sector,i)=>({sector,region:'USA',symbol:'DEMO'+i,price_basis:'fiktiv',series:Array.from({length:13},(_,j)=>({date:new Date(Date.now()-(12-j)*31*864e5).toISOString().slice(0,10),close:100+i*5+j*(i%2?-.3:.8)}))}));
   return ok({dashboard,regions:['USA'],markets,history:[],fx_quotes:[]});
  }
  if(route==='reports/candidate-registry')return ok({candidates:[]});
  if(route==='v1/hotwatch/sessions')return ok({sessions:u.searchParams.get('view')==='history'?[]:sessions,kill_switch:{killed:false},worker:null,discovery_attempts:[],truncated:false});
  if(route.startsWith('v1/hotwatch/sessions/')&&route.endsWith('/events'))return ok({items:[],truncated:false});
  if(route.startsWith('v1/hotwatch/sessions/')&&route.endsWith('/samples'))return ok({items:Array.from({length:12},(_,i)=>({data:{price:String(50+i*.1),event_time:new Date(Date.now()-i*60000).toISOString(),currency:'DKK',interval_s:60,session_key:'demo'}})),truncated:false});
  if(route.startsWith('v1/hotwatch/sessions/')){const id=decodeURIComponent(route.split('/')[3]||'');return ok({session:sessions.find(s=>s.watch_id===id)||sessions[0]})}
  if(route==='market/quote'){
   const id=payload.holding_asset_id||payload.asset_id||'synthetic-asset-TSLA',p=position(id),t=Date.now(),price=Number(p?.price?.amount||50);
   const series=Array.from({length:24},(_,i)=>{const time=new Date(t-(23-i)*3600000);return {price:(price*(.98+i*.0009+.004*Math.sin(i*.7))).toFixed(4),epoch:time.getTime()/1000,timestamp:time.toISOString(),date:time.toISOString().slice(0,10)}});
   return ok({asset_id:id,ticker:p?.ticker||'TEST',name:p?.name||'Testaktie',exchange:'TEST',asset_type:'CS',currency:p?.price?.currency||'DKK',price:String(price),price_time:now(),fetched_at:now(),daily_change_percent:'1.6',daily_change:'0.8',daily_note:null,week_change_percent:'2.0',series});
  }
  if(route==='trade/preview')return ok({read_only:true,estimate:{quote:{message:'Simuleret estimat'},buying_power_checked:true,accounts:[]},asset:{},payload:{orders:[]}});
  if(route==='trade/search')return ok({assets:demo.state.dashboard.positions.map(p=>({asset_id:p.asset_id,name:p.name,ticker:p.ticker,currency:p.price?.currency||'DKK',isin:'TEST'}))});
  if(route==='trade/estimate'){
   const sell=payload.size_mode==='percent',p=position(payload.asset_id),portfolio=Number(payload.portfolio_id)||1,currency=payload.currency||'DKK';
   const order={assetId:payload.asset_id||'synthetic-asset-TSLA',side:sell?'SELL':'BUY',currency,orderType:payload.order_type||'MARKET',timeInForce:'DAY',...(sell?{shares:'1'}:payload.size_mode==='shares'?{shares:String(payload.size)}:{amount:String(payload.size)}),...(payload.limit_price?{limitPrice:String(payload.limit_price)}:{})};
   return ok({proposal:{id:++serial,status:'estimated',review_token:'demo-only',portfolio_id:portfolio,kind:'direct',payload:{orders:[order]},asset:{asset:{name:p?.name||'Testaktie',isin:'TEST',currency}},estimate:{quote:{besked:'Fiktivt estimat – ingen ordre',omkostninger:'Ikke beregnet'},active_orders:[],buying_power_checked:true},sell_basis:sell?{quantity:'2',percentage:String(payload.size),shares:'1'}:null}});
  }
  if(route==='trade/send')return ok({proposal:{status:'sent',response:{status:'SIMULERET'}}});
  if(route==='trade/history')return ok({proposals:[]});
  if(route==='push/config')return ok({available:false});
  if(route==='portfolios/data'||route==='portfolios/sync')return ok({complete:true,cached:true,errors:[],ok:true});
  return bad();
 };
})();

